"""Load only project-controlled artefacts; validate CSV input before prediction."""
from io import BytesIO
import csv
import json
import joblib
import pandas as pd
from src.data import ROOT, FEATURES, clean_frame, sha256

def load_bundle():
    directory = ROOT / 'models'
    manifest = json.loads((directory/'manifest.json').read_text())
    path = directory/'final.joblib'
    if sha256(path) != manifest['sha256']:
        raise ValueError('Model integrity check failed. Regenerate trusted project artefacts.')
    # The fixed local file is generated by src.train. Never accept upload paths.
    return joblib.load(path)

def parse_upload(content):
    if len(content)>5*1024*1024:
        raise ValueError('CSV exceeds the 5 MB limit.')
    try:
        text = content.decode('utf-8-sig')
        header = next(csv.reader(text.splitlines()))
        if len(header)!=len(set(header)):
            raise ValueError('Duplicate column names are not allowed.')
        d = pd.read_csv(BytesIO(content),dtype=str,keep_default_na=False)
    except (UnicodeError, pd.errors.ParserError, pd.errors.EmptyDataError, StopIteration) as exc:
        raise ValueError('Upload a nonempty UTF-8 CSV with a header.') from exc
    if len(d)>10000:
        raise ValueError('Upload at most 10,000 rows at a time.')
    return clean_frame(d)

def predict_frame(bundle, frame):
    d = clean_frame(frame)
    result = d.copy()
    result['churn_probability'] = bundle['pipeline'].predict_proba(d[FEATURES])[:,1]
    result['risk_category'] = result.churn_probability.ge(bundle['threshold']).map({True:'Review priority',False:'Below review threshold'})
    return result

def safe_csv(frame):
    """Neutralise spreadsheet formula injection in any exported text cells."""
    d = frame.copy()
    for c in d.select_dtypes(include=['object','string']).columns:
        d[c] = d[c].map(lambda x: "'"+x if isinstance(x,str) and x.lstrip().startswith(('=','+','-','@','\t','\r')) else x)
    return d.to_csv(index=False).encode('utf-8')
